// "Remove selected" (app/bulk_select.js) on the Vault page's own markup,
// generated by the Go test handlers/vault TestVaultPageFixtureIsCurrent: one
// frozen pledge (the first row) and three that can go. Here and not next to
// the script because webpack builds every .js under app/ as an entry.
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { JSDOM } from 'jsdom';

const PAGE = readFileSync(new URL('./__fixtures__/vault-page.html', import.meta.url), 'utf8');
const FROZEN = '4897aacef168307328e121694dcdb8407e6d62cc';

const dom = new JSDOM(`<!doctype html><html lang="ru"><body>${PAGE}</body></html>`, { url: 'https://webtor.io/ru/vault' });
global.window = dom.window;
global.document = dom.window.document;
let answer = true;
const asked = [];
const tracked = [];
window.umami = { track: (name, data) => tracked.push([name, data]) };
// The script calls the global confirm, as a browser's window is the global.
global.confirm = (msg) => { asked.push(msg); return answer; };

// lib/av registers the init against the element holding the script.
const root = document.querySelector('[data-bulk-confirm]');
const script = root.querySelector('script[src="/assets/bulk_select.js"]');
Object.defineProperty(document, 'currentScript', { configurable: true, get: () => script });
await import('../app/bulk_select.js');
const [target, init] = window.av[0];
assert.equal(target, root);
init.call(target);

const form = document.getElementById('bulk-remove');
// What lib/async.js does with the form: takes the submit, sends FormData.
const sent = [];
form.addEventListener('submit', (e) => {
    e.preventDefault();
    const fd = new window.FormData(form);
    // One field, never a part per box (web.FormBulkIDs).
    assert.deepEqual(fd.getAll('resource_id'), []);
    sent.push(fd.get('resource_ids').split(','));
});
const $ = (sel) => root.querySelector(sel);
const boxes = () => [...root.querySelectorAll('input.js-bulk-box')];
const checked = () => boxes().filter((b) => b.checked).map((b) => b.value);
const click = (el) => el.dispatchEvent(new window.MouseEvent('click', { bubbles: true, cancelable: true }));
const tick = (box) => { box.checked = !box.checked; box.dispatchEvent(new window.Event('change', { bubbles: true })); };

test('the toggle shows itself and enters select mode, nothing selected yet', () => {
    assert.ok(!$('.js-bulk-toggle').classList.contains('hidden'));
    assert.ok(!root.hasAttribute('data-bulk-on'));
    click($('.js-bulk-toggle'));
    assert.ok(root.hasAttribute('data-bulk-on'));
    assert.ok($('.js-bulk-submit').disabled);
    assert.equal($('.js-bulk-count').textContent, '');
});

test('select all takes every pledge but the frozen one', () => {
    click($('.js-bulk-all'));
    assert.equal(boxes().length, 4);
    assert.deepEqual(checked().sort(), boxes().map((b) => b.value).filter((v) => v !== FROZEN).sort());
    assert.equal($('.js-bulk-count').textContent, ' (3)');
    assert.ok(!$('.js-bulk-submit').disabled);
});

test('a "no" to the confirmation sends nothing, a "yes" sends the checked ids', () => {
    answer = false;
    click($('.js-bulk-submit'));
    assert.equal(sent.length, 0);
    assert.equal(tracked.length, 0, 'a declined removal is not counted');
    assert.equal(asked.at(-1), root.dataset.bulkConfirm);
    answer = true;
    $('.js-bulk-submit').click();
    assert.deepEqual(sent.at(-1).sort(), checked().sort());
    assert.deepEqual(tracked, [['bulk-remove', { path: '/vault/remove', count: 3 }]]);
});

test('a table re-rendered inside the root keeps the selection on the rows still there', () => {
    const table = document.getElementById('vault-pledges');
    const rows = table.querySelectorAll('tbody tr');
    const gone = rows[rows.length - 1].querySelector('input.js-bulk-box').value;
    const keep = checked().filter((v) => v !== gone);
    rows[rows.length - 1].remove();
    // The async reload: fresh markup, every box unchecked, then the event.
    table.innerHTML = table.innerHTML.replaceAll(' checked=""', '');
    for (const b of boxes()) b.checked = false;
    window.dispatchEvent(new window.CustomEvent('async', { detail: { target: table } }));
    assert.deepEqual(checked().sort(), keep.sort());
    assert.equal($('.js-bulk-count').textContent, ` (${keep.length})`);
});

test('ticking a box by hand counts it; cancel leaves select mode with nothing kept', () => {
    tick(boxes().find((b) => b.checked));
    const n = checked().length;
    assert.equal($('.js-bulk-count').textContent, ` (${n})`);
    click($('.js-bulk-cancel'));
    assert.ok(!root.hasAttribute('data-bulk-on'));
    assert.deepEqual(checked(), []);
    assert.ok($('.js-bulk-submit').disabled);
});

test('select all stops at the server\'s bound, and a box past it does not stay ticked', () => {
    const tbody = document.querySelector('#vault-pledges tbody');
    for (let i = 0; i < 1005; i++) {
        const tr = document.createElement('tr');
        tr.innerHTML = `<td><input type="checkbox" class="js-bulk-box" value="extra${i}"></td>`;
        tbody.appendChild(tr);
    }
    click($('.js-bulk-toggle'));
    click($('.js-bulk-all'));
    assert.equal(checked().length, 1000);
    const spare = boxes().find((b) => !b.checked && !b.disabled);
    tick(spare);
    assert.equal(spare.checked, false);
    assert.equal(checked().length, 1000);
    assert.equal($('.js-bulk-ids').value.split(',').length, 1000);
});
